<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\Event;

use Override;
use Civi\Lughauth\Features\Notification\Message\Domain\Message;
use Civi\Lughauth\Shared\Event\PublicEvent;

class MessageUpdateEvent extends MessageEvent implements PublicEvent
{
    public function __construct(
        Message $payload,
        public readonly Message $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'message.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
